import json
import sqlite3
import sys
import hashlib
import math

def generate_token(secret, id_str):
    combined = f"{secret}{id_str}".encode('utf-8')
    h = hashlib.sha256(combined)
    token = h.hexdigest()
    return token[:64].lower()

def evaluate_expression(expr, row):
    try:
        # Replace column names with their values from the row
        for col, val in row.items():
            if val is None:
                continue
            if isinstance(val, int):
                expr = expr.replace(col, str(val))
            else:
                return None
        # Evaluate the expression
        try:
            result = eval(expr)
            if isinstance(result, int):
                return result
            else:
                return None
        except:
            return None
    except:
        return None

def process_row(row, expr):
    value = evaluate_expression(expr, row)
    token = generate_token(secret, str(row.get('id')))
    return {
        **row,
        'value': value,
        'token': token
    }

def main():
    if len(sys.argv) != 2:
        print("Usage: python job_report.py job.json", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        job = json.load(f)

    db_path = job['db']
    sql = job['sql']
    params = job['params']
    expr = job['expr']
    secret = job['secret']

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    cursor.execute(sql, params)
    rows = cursor.fetchall()

    column_names = [desc[0] for desc in cursor.description]

    for row in rows:
        row_dict = dict(zip(column_names, row))
        processed_row = process_row(row_dict, expr)
        print(json.dumps(processed_row))

    conn.close()

if __name__ == "__main__":
    main()
